{# SAC AMC Work Order to SSD - CRM Contract print format #}
{% set wo_number = doc.name %}
{% set branch_address = frappe.db.get_value("Region Branches", doc.branch, "branch_address") if doc.branch else "" %}
{% set address_name = doc.customer_address or doc.shipping_address %}
{% set address = (frappe.get_doc("Address", address_name).get_display() if address_name and frappe.db.exists("Address", address_name) else (address_name or "")) %}
{% set amc_rows = (doc.product_details or []) | selectattr("type", "equalto", "AMC") | list %}
{% set amc_start = doc.start_date or (amc_rows | map(attribute="start_date") | select | min if amc_rows | map(attribute="start_date") | select | list else None) %}
{% set amc_end = doc.expiry_date or (amc_rows | map(attribute="expiry_date") | select | max if amc_rows | map(attribute="expiry_date") | select | list else None) %}
{% set lcc = doc.get("lcc_category") or "DIAMOND" %}

<style>
  .wo, .tnc {
    font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;
    font-size: 11.5px;
    line-height: 1.5;
    color: #222;
  }
  .wo p, .tnc p { margin: 0; }
  .wo table, .tnc table { width: 100%; border-collapse: collapse; }

  /* ---- Letterhead ---- */
  .print-format .wo td, .print-format .wo th,
  .print-format .tnc td { padding: 0 !important; vertical-align: top !important; }
  .wo-head { position: relative; }
  .wo-logo { width: 190px !important; height: auto; display: block; }
  .wo-company { margin-top: 10px; font-size: 13px; font-weight: bold; color: #1f3a5f; }
  .wo-branch { font-size: 10px; color: #555; line-height: 1.4; margin-top: 2px; }
  .wo-annexure { position: absolute; top: 0; right: 0; white-space: nowrap;
                 font-size: 10px; font-weight: bold; color: #1f3a5f; letter-spacing: 1px;
                 text-transform: uppercase; border: 1px solid #1f3a5f; padding: 2px 8px; }
  .wo-rule { border-top: 2px solid #1f3a5f; margin: 10px 0 18px; }

  /* ---- Title ---- */
  .wo-title { text-align: center; font-size: 15px; font-weight: bold;
              letter-spacing: 0.5px; text-transform: uppercase; color: #1f3a5f; margin-bottom: 16px; }

  /* ---- Meta block ---- */
  .print-format .wo-meta td { padding: 2px 0 !important; }
  .wo-meta td.lbl { width: 22%; font-weight: bold; color: #444; }
  .wo-to { margin-top: 14px; }
  .wo-to .lbl { font-weight: bold; color: #444; }
  .wo-to .name { font-size: 13px; font-weight: bold; margin-top: 2px; }

  .wo-subject { margin: 16px 0 10px; padding: 7px 10px; background: #f1f4f8;
                border-left: 3px solid #1f3a5f; }
  .wo-body p { margin-top: 8px; text-align: justify; }

  /* ---- AMC table ---- */
  .amc-table { margin: 14px 0 6px; }
  .print-format .amc-table th { padding: 7px 5px !important; vertical-align: middle !important; }
  .print-format .amc-table td { padding: 9px 6px !important; vertical-align: middle !important; }
  .amc-table th { background: #1f3a5f; color: #fff; border: 1px solid #1f3a5f;
                  font-size: 10.5px; font-weight: bold; text-align: center; padding: 7px 5px; }
  .amc-table td { border: 1px solid #b8c2cf; font-size: 11px; text-align: center;
                  vertical-align: middle; padding: 9px 6px; }
  .amc-table td.left { text-align: left; }
  .amc-table td.num { text-align: right; white-space: nowrap; }
  .amc-table tr:nth-child(odd) td { background: #f7f9fb; }

  /* ---- Signature ---- */
  .wo-sign { margin-top: 34px; }
  .wo-sign .firm { font-weight: bold; margin-top: 2px; }
  .wo-sign .space { height: 70px; }
  .wo-sign .line { width: 200px; border-top: 1px solid #222; padding-top: 4px; font-weight: bold; }

  /* ---- Terms & Conditions ---- */
  .tnc { font-size: 10.5px; line-height: 1.45; }
  .tnc-title { text-align: center; font-size: 13px; font-weight: bold; text-transform: uppercase;
               color: #1f3a5f; padding-bottom: 6px; border-bottom: 2px solid #1f3a5f; margin-bottom: 10px; }
  .tnc h4 { font-size: 11.5px; font-weight: bold; color: #1f3a5f; margin: 12px 0 4px;
            padding-bottom: 2px; border-bottom: 1px solid #d5dbe3; }
  .tnc ol { margin: 0; padding-left: 20px; }
  .tnc li { margin-bottom: 3px; text-align: justify; }
  .tnc p { margin-bottom: 5px; text-align: justify; }
  .tnc-accept { margin-top: 26px; page-break-inside: avoid; }
  .print-format .tnc-accept td { padding: 10px 0 2px !important; vertical-align: bottom !important; }
  .tnc-accept td.lbl { width: 22%; font-weight: bold; }
  .tnc-accept td.fill { border-bottom: 1px solid #222; }
</style>

<div class="wo">

  <div class="wo-head">
    <div class="wo-annexure">Annexure - 1</div>
    <img class="wo-logo" src="/files/logo_hi-m.png">
    <div class="wo-company">Hi-M Solutek India Pvt. Ltd</div>
    {% if branch_address %}<div class="wo-branch">{{ branch_address }}</div>{% endif %}
  </div>
  <div class="wo-rule"></div>

  <div class="wo-title">SAC AMC Work Order to SSD</div>

  <table class="wo-meta">
    <tr>
      <td class="lbl">Work Order No.</td>
      <td>: {{ wo_number }}</td>
    </tr>
    <tr>
      <td class="lbl">Date</td>
      <td>: {{ frappe.utils.formatdate(doc.date, "dd-MMM-yyyy") if doc.date else "" }}</td>
    </tr>
  </table>

  <div class="wo-to">
    <div class="lbl">To,</div>
    <div class="name">{{ doc.ssd_name_dealer or "" }}</div>
  </div>

  <div class="wo-subject">
    <b>Sub:</b> Work order for doing AMC (Annual Maintenance Contract) on behalf of Hi-M.Solutek
  </div>

  <div class="wo-body">
    <p>Dear Sir,</p>
    <p>We hereby confirm the work order for providing services under AMC as per following details:</p>
  </div>

  <table class="amc-table">
    <tr>
      <th width="15%">Customer Name</th>
      <th width="15%">Project Name</th>
      <th width="28%">Address</th>
      <th width="13%">AMC Start Dt.</th>
      <th width="13%">AMC End Dt.</th>
      <th width="16%">Customer Order Value (Basic)</th>
    </tr>
    <tr>
      <td class="left">{{ doc.customer_name or "" }}</td>
      <td class="left">{{ doc.project or "" }}</td>
      <td class="left">{{ address }}</td>
      <td>{{ frappe.utils.formatdate(amc_start, "dd-MMM-yyyy") if amc_start else "" }}</td>
      <td>{{ frappe.utils.formatdate(amc_end, "dd-MMM-yyyy") if amc_end else "" }}</td>
      <td class="num">&#8377; {{ frappe.utils.fmt_money(doc.amount or 0, precision=0) }}</td>
    </tr>
  </table>

  <div class="wo-body">
    <p>Please acknowledge and share the acceptance of work order via registered email id (with Hi-M.Solutek).</p>
    <p>AMC claim/invoice will be processed as per your LCC category offered by LG for the year in which customer AMC billing has been booked.</p>
    <p>Your present LCC category is <b>{{ lcc }}</b>, AMC payment may vary as per LCC category, please refer LCC category offering for AMC Allocation for dealers.</p>
    <p>Terms &amp; Conditions is as per enclosed Annexure.</p>
  </div>

  <div class="wo-sign">
    <p>Yours Sincerely,</p>
    <p class="firm">For Hi-M.Solutek India Pvt. Ltd</p>
    <div class="space"></div>
    <div class="line">Authorized Signatory</div>
  </div>

</div>

<div class="page-break"></div>

<div class="tnc">

  <div class="tnc-title">Annexure - AMC Work Order to SSD - Terms and Conditions</div>

  <h4>Scope</h4>
  <ol>
    <li>All call should be registered at Hi-M.Solutek B2B SAC (System Air conditioner) call centre no. 1800-180-3575.</li>
    <li>Four Preventive maintenance (PM) services to customer - Quarterly every year (03 Nos. Dry &amp; 01 No. Wet service).</li>
    <li>Complaint call should be attended on the same day if received before 3:00 pm, if received after 3:00 pm should be attended on next day before 12 noon.</li>
    <li>Complaint should be resolved/completed within a day for minor complaints and within 2 days for major complaints.</li>
    <li>Replacement of all parts, refrigerant and labour except compressor is in scope of Dealer.</li>
    <li>To keep all the spares inventory at his Store / Customer site as per the agreement/contract. All the spares inventories should kept by Dealer based on the equipment used at site for providing fast service without penalty.</li>
    <li>To keep record of all the reports for complaints/routine services done at the customer site.</li>
    <li>Dealer has to give declaration for Part consumed in AMC other than compressor as per standard process given by Hi-M.Solutek</li>
    <li>Any special service condition specified in customer Purchase order (PO) will as applicable to Dealer back to back basis.</li>
    <li>In case of BECON Cloud (TMS Site), support for controller installation, cable supply &amp; installation and commissioning to be provided by Dealer at customer site.</li>
    <li>MSL for spares including compressors to be maintained at site by Dealer.</li>
    <li>Compressor cost shall be reimbursed thru P2P or P2C.</li>
  </ol>

  <h4>Quality</h4>
  <ol>
    <li>Dealer shall use trained and experienced Engineers, having all necessary skills to make sure satisfactory completion of work at site. Dealer shall provide the services as per schedule.</li>
    <li>Dealer shall comply with all applicable laws and provide records for such compliance to Hi-M.Solutek as &amp; when required.</li>
    <li>Dealer shall use genuine spares while repairing &amp; all other service materials should be used as per guidelines only.</li>
  </ol>

  <h4>Price &amp; Payment</h4>
  <ol>
    <li>Terms of payments for AMC will be back to back as per Customer PO.</li>
    <li>Payment will only be processed once it is credited in to company account/s from the customer.</li>
    <li>Payment to ASP/Dealer will be as per sharing policy.</li>
    <li>In case of any delay in payment by customer, Dealer will cooperate fully in following up the payment from the customer.</li>
    <li>For all Yearly AMC contracts (above 1.0 Lacs basic AMC value), payment terms for Dealer will remain same as previous guide lines (Half yearly)</li>
  </ol>

  <h4>Penalty for non-compliance of service obligation</h4>
  <ol>
    <li>In case of Failure to provide the service during the contract period as per company policies, the cost will be debited as actual &amp; this will be considered while regular Dealer evaluation by Hi-M.Solutek.</li>
    <li>Penalty clause will be applicable as per customer PO.</li>
    <li>Preventive Maintenance reports to be submitted to Hi-M.Solutek on quarterly basis, failing which "10% penalty of contract" will be imposed for every quarter report.</li>
  </ol>

  <h4>Insurance</h4>
  <ol>
    <li>Dealer should ensure the insurance of all the employees to be deputed at the customer site in all the formats.</li>
    <li>Dealer shall submit the insurance papers i.e. ESI, PF, Attendance, salary compensation etc. to customer &amp; company, as per government regulations.</li>
  </ol>

  <h4>Confidentiality</h4>
  <p>Dealer shall in all events maintain confidentiality for the work being carried out, including data privacy. Dealer shall treat all information as strictly confidential and protect all information and documents received or obtained. Dealer will not disclose or divulge such Confidential Information to any third party, unless prior written consent of Hi-M.Solutek has been sought or where such Confidential Information is required to be disclosed under the Laws, then sufficient prior written notice of the proposed disclosure is given to Hi-M.Solutek. Further the Dealer agrees that it will use Confidential Information only to fulfil its obligations in terms of the work to be carried out. In all instances where the BECON facility is being provided, personal information of customers shall be maintained, stored &amp; utilized in an applicable manner in compliance with all laws. A Data Privacy Manager, as determined by Company, shall be responsible for all the information. And confidentiality shall be maintained.</p>

  <h4>Termination</h4>
  <p>Company shall forthwith have the right to terminate this contact in event of a) any non-compliance / failure to provide services by Dealer as per the agreement b) Usage of forged material/spares by Dealer. Hi-M.Solutek is authorised to de-scope the work from of the service provider due to non-performance/non-timely completion etc. and any extra premium paid to new Service Provider shall be debited to Dealer. It is responsibility of Service provider to hand over the machinery to Hi-M.Solutek authorised person in good condition or the amount will be debited to dealer as decided by Hi-M.Solutek Engineer-In-Charge.</p>

  <h4>Indemnity</h4>
  <p>Service Provider shall defend, indemnify, release and hold harmless Hi-M.Solutek, its affiliates, and their respective directors, officers, employees, agents, successors and assigns from and against any liability, loss, taxes, interest, penalties, damage, cost or expense (including reasonable attorneys’ fees), allegations or claims ("Claims") that arise, directly or indirectly, from: (a) death of or injury to any person, damage to any property or any other damage or loss caused by Service Provider or its Personnel; (b) breach of the terms of this Agreement, including the representations, warranties and covenants provided herein; (c) negligence, strict liability intentional misconduct by Dealer or its Personnel; (d) deficiency in Services; (e) act or omission by Service Provider and/or its Personnel, including without limitation any breach or default under this Agreement or the Order. Further, the Service Provider’s duty to defend is independent of its duty to indemnify. Service Provider’s obligations under this Section are independent of all of its other obligations under this Agreement.</p>
  <p>The Service Provider shall be solely responsible towards any claims, dues, liabilities, loss, damages, expenses or any liability arising out of and/or in relation to this agreement due to any reason, whatsoever. In any event, if Hi-M.Solutek is required to pay to any authority and/or to any third party with respect to and/or in connection with this agreement, due to any reason, whatsoever, the Service Provider shall be liable to refund/reimburse the same without any delay. In such case Hi-M.Solutek will have the right to deduct/recover the payment in such cases, if payment is not made by Service Provider.</p>
  <p>Service Provider will not make any claim or raise any dispute before the Customer. All the claims / disputes if any, shall be raised before Hi-M.Solutek only which shall be settled as per relevant provisions in the Agreement. The Service Provider is not allowed to make any claim or dispute, if any, against Customer before any forum/court.</p>
  <p><b>Extension of AMC period</b> - If there is any extension of AMC period as per direction of end customer (Employer) then it shall be effective unless it is amended signed WO / written Approval issued by Hi-M.Solutek.</p>
  <p><b>Work Completion / Handing over</b> - After completion of AMC period, customer completion certificate is required &amp; it is the responsibility of the Service Provider to obtain the same.</p>

  <h4>Arbitration</h4>
  <p>In the event of any dispute arising out of or related to this work order which cannot be resolved through negotiations between the parties, the same shall be settled through sole arbitrator appointed by Hi-M.Solutek in terms of the arbitration &amp; Conciliation Act and rules thereof. The seat of arbitration shall be New Delhi and language shall be English.</p>

  <table class="tnc-accept">
    <tr><td colspan="2" style="font-weight:bold; color:#1f3a5f;">Acceptance By</td></tr>
    <tr style="height:60px;"><td class="lbl">Authorized Signatory</td><td></td></tr>
    <tr style="height:34px;"><td class="lbl">Dealer Name</td><td class="fill">{{ doc.ssd_name_dealer or "" }}</td></tr>
    <tr style="height:34px;"><td class="lbl">Sign / Stamp / Date</td><td class="fill"></td></tr>
  </table>

</div>
